/** Native scroll snap; the buttons nudge. */
export function Carousel({ className, children, "aria-label": ariaLabel = "Carousel", ...props }: CarouselProps) {
  const trackRef = React.useRef<HTMLDivElement>(null);
  const nudge = (dir: 1 | -1) => {
